std::vector<std::string> lookUpNumbers(const std::vector<std::string>& names,
                                       const std::vector<std::string>& numbers,
                                       const std::vector<std::string>& queries) {
    std::unordered_map<std::string, std::string> book;
    for (size_t i = 0; i < names.size(); i++) {
        book[names[i]] = numbers[i];
    }
    std::vector<std::string> answers;
    for (const std::string& name : queries) {
        auto it = book.find(name);
        answers.push_back(it != book.end() ? it->second : "not found");
    }
    return answers;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::string> names(n), numbers(n);
    for (int i = 0; i < n; i++) {
