package main

import "fmt"

func lookUpNumbers(names, numbers, queries []string) []string {
	book := make(map[string]string)
	for i, name := range names {
		book[name] = numbers[i]
	}
	answers := make([]string, 0, len(queries))
	for _, name := range queries {
		if number, ok := book[name]; ok {
			answers = append(answers, number)
		} else {
			answers = append(answers, "not found")
		}
	}
	return answers
}

func main() {
	var n int
	fmt.Scan(&n)
	names := make([]string, n)
	numbers := make([]string, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&names[i], &numbers[i])
	}
	var q int
	fmt.Scan(&q)
	queries := make([]string, q)
	for i := 0; i < q; i++ {
		fmt.Scan(&queries[i])
	}
	for _, answer := range lookUpNumbers(names, numbers, queries) {
		fmt.Println(answer)
	}
}
